theorem abs_tailStep_sub_le (a : PartialQuotient) {x y : ℝ}
    (hx : x ∈ Set.Icc (0 : ℝ) 1) (hy : y ∈ Set.Icc (0 : ℝ) 1) :
    |1 / ((a.1 : ℝ) + x) - 1 / ((a.1 : ℝ) + y)| ≤ |x - y|

theorem abs_tailMap_sub_le (w : Word) {x y : ℝ}
    (hx : x ∈ Set.Icc (0 : ℝ) 1) (hy : y ∈ Set.Icc (0 : ℝ) 1) :
    |tailMap w x - tailMap w y| ≤ |x - y| / 4 ^ (w.length / 2)

theorem abs_tailMap_le_cylinder (w : Word) {x y : ℝ}
    (hx : x ∈ Set.Icc (0 : ℝ) 1) (hy : y ∈ Set.Icc (0 : ℝ) 1) :
    |tailMap w x - tailMap w y| ≤ 1 / 4 ^ (w.length / 2)

theorem minkowskiSum_mono {X₁ X₂ Y₁ Y₂ : Set ℝ}
    (hX : X₁ ⊆ X₂) (hY : Y₁ ⊆ Y₂) :
    minkowskiSum X₁ Y₁ ⊆ minkowskiSum X₂ Y₂

theorem HallNode.dist_le_cylinder {v : HallNode} {x y : ℝ}
    (hx : x ∈ v.interval) (hy : y ∈ v.interval) :
    dist x y ≤ 1 / 4 ^ (v.word.length / 2)

theorem nodeAtLevel_allowed_rank {n : ℕ} {v : HallNode}
    (hv : v ∈ nodesAtLevel n) :
    v.WordAllowed ∧ n ≤ v.rank

theorem exists_list_max {α : Type*} (f : α → ℝ) {l : List α}
    (hl : l ≠ []) :
    ∃ m ∈ l, ∀ a ∈ l, f a ≤ f m

theorem forestTarget_erase_split {chosen : WorkNode} {forest : List WorkNode}
    (hchosen : chosen ∈ forest) {v : HallNode} {r : ℕ}
    (hchosen_eq : chosen = ⟨v, r + 1⟩) :
    forestTarget forest =
      forestTarget (⟨v.leftChild, r⟩ :: ⟨v.rightChild, r⟩ ::
        forest.erase chosen)

theorem forestWork_split_lt {v : HallNode} {r : ℕ}
    {chosen : WorkNode} {forest : List WorkNode}
    (hchosen : chosen ∈ forest) (hchosen_eq : chosen = ⟨v, r + 1⟩) :
    forestWork (⟨v.leftChild, r⟩ :: ⟨v.rightChild, r⟩ ::
      forest.erase chosen) < forestWork forest

theorem lambda_le_of_digits_le (A : BiSequence) {M : ℝ}
    (hA : ∀ i, ((A i).1 : ℝ) ≤ M) (i : ℤ) :
    lambda A i ≤ M + 2

theorem anchor_regions_disjoint {p n m : ℕ}
    (hn : InAnchorRegion p n) (hm : InAnchorRegion p m) :
    n = m

theorem regionOwner_eq_of_mem {p n : ℕ}
    (h : ∃ m, InAnchorRegion p m) (hn : InAnchorRegion p n) :
    regionOwner p h = n
